const slug = (value) => String(value || "").toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

export const NIGERIA_FIVE_STATE_PRIMARY_CARE_NOV2026 = facilityRows.map((row) => {
  const place = [row.ward_standard && row.ward_standard + " ward", row.lga_standard + " LGA"].filter(Boolean).join(", ");
  const level = row.facility_type || row.facility_level + " health facility";
  return {
    id: "nigeria-grid3-" + slug(row.state) + "-" + slug(row.unique_id),
    name: row.facility_name + " — public primary-care access",
    primaryCategory: "programs",
    resourceType: "Public primary-health facility · source-reported functional · confirm before travel",
    description: "CIESIN/Columbia University's 2026 GRID3 NGA Health Facilities v4.0 layer identifies " + row.facility_name + " (" + level + ") in " + place + ", " + row.state + " State. The source reports this record as functional, but its facility layer is explicitly non-exhaustive and not field-validated; this status is not a live check that the facility is open or has capacity today. The dataset does not establish current hours, a phone contact, service availability, eligibility, accessibility, or fees. Contact the state primary-health authority or facility before travelling. This is a general primary-care access point, not confirmation of specialist mental-health, substance-use, or recovery treatment.",
    city: row.lga_standard,
    state: row.state,
    country: "Nigeria",
    region: place + ", " + row.state + " State, Nigeria",
    locationLine: place + " · coordinates " + row.latitude + ", " + row.longitude + " · source status: functional; confirm current operation and services",
    latitude: row.latitude,
    longitude: row.longitude,
    sourceRecordId: row.unique_id,
    link: SOURCE_ITEM_URL,
    sourceEvidenceUrl: SOURCE_URL,
    source: PUBLISHER,
    checkedAt: reviewedAt,
    sourceReviewedAt: reviewedAt,
    sourceReviewed: true,
    sourceReviewStatus: "opened-public-source",
    phoneConfirmed: false,
    exhaustiveCoverage: false,
    verified: true,
  };
});
